class C{String s(boolean p,String I){var g=I.lines().toList();int R=g.size(),C=g.get(0).length();long A=0;int[]q=new int[R*C],v=new int[R*C];for(int r=0;r<R;r++){var s=g.get(r);for(int c=0;c<C;c++){char h=s.charAt(c);if(h<48|h>57)continue;int b=c,n=0;for(;c<C&&(h=s.charAt(c))>47&h<58;c++)n=n*10+h-48;boolean o=0>1;var z=new java.util.HashSet<Integer>();for(int y=Math.max(0,r-1);y<=Math.min(R-1,r+1);y++)for(int x=Math.max(0,b-1);x<=Math.min(C-1,c);x++){h=g.get(y).charAt(x);if((h<48|h>57)&h!=46)o=1>0;if(h==42)z.add(y*C+x);}if(p&o)A+=n;for(int x:z){q[x]++;v[x]=v[x]<1?n:v[x]*n;}c--;}}if(!p)for(int i=0;i<q.length;i++)if(q[i]==2)A+=v[i];return A+"";}}
